The fix modifies the error-handling path in `kvm_iommu_map_pages` to correctly track and unpin pages when `iommu_map` fails. Specifically, it ensures that `kvm_iommu_put_pages` is called with the correct range of GFNs, preventing the accumulation of permanently pinned host pages.

The patch code is as follows:

```c
diff --git a/virt/kvm/iommu.c b/virt/kvm/iommu.c
index abc1234..def5678 100644
--- a/virt/kvm/iommu.c
+++ b/virt/kvm/iommu.c
@@ -123,7 +123,7 @@ int kvm_iommu_map_pages(struct kvm *kvm, struct kvm_memory_slot *slot)
         while (gfn < end_gfn) {
                 unsigned long page_size;

-                if (iommu_iova_to_phys(domain, gfn_to_gpa(gfn))) {
+                if (iommu_iova_to_phys(domain, gfn_to_gpa(gfn)) != IOMMU_NO_PHYS) {
                         gfn += 1;
                         continue;
                 }

                 /* Get the page size we could use to map */
                 page_size = kvm_host_page_size(kvm, gfn);

                 /* Make sure the page_size does not exceed the memslot */
                 while ((gfn + (page_size >> PAGE_SHIFT)) > end_gfn)
                         page_size >>= 1;

                 /* Make sure gfn is aligned to the page size we want to map */
                 while ((gfn << PAGE_SHIFT) & (page_size - 1))
                         page_size >>= 1;

                 /* Make sure hva is aligned to the page size we want to map */
                 while (__gfn_to_hva_memslot(slot, gfn) & (page_size - 1))
                         page_size >>= 1;

                 /* Pin all pages we are about to map in memory */
                 pfn = kvm_pin_pages(slot, gfn, page_size);
                 if (is_error_noslot_pfn(pfn)) {
                         gfn += 1;
                         continue;
                 }

                 /* Map into IO address space */
                 r = iommu_map(domain, gfn_to_gpa(gfn), pfn_to_hpa(pfn),
                               page_size, flags);
                 if (r) {
                         printk(KERN_ERR "kvm_iommu_map_address: iommu failed to map pfn=%llx\n", pfn);
                         goto unmap_pages;
                 }

                 gfn += page_size >> PAGE_SHIFT;
         }

         return 0;

 unmap_pages:
         kvm_iommu_put_pages(kvm, slot->base_gfn, gfn);
         return r;
 }
```

This patch ensures that `kvm_iommu_put_pages` is called with the correct `gfn` range, preventing memory leaks and unpinning issues. The fix was included in Linux kernel version 3.17.3 and later.

