        if (!io_sqring_full(ctx))
            break;

        schedule();
    } while (!signal_pending(current));

    finish_wait(&ctx->sqo_sq_wait, &wait);
out:
    return ret;
}
```

The `finish_wait()` call is bypassed when `ctx->sqo_dead` is set, leading to the use-after-free. The fix in kernel 5.10.155 ensures proper wait queue cleanup even when `sqo_dead` is set.

