```c
int detach_capi_ctr(struct capi_ctr *ctr)
{
    int err = 0;

    mutex_lock(&capi_controller_lock);

    ctr_down(ctr, CAPI_CTR_DETACHED);

    if (ctr->cnr < 1 || ctr->cnr > MAX_CAPI_CONTROLLERS ||
        capi_controller[ctr->cnr - 1] != ctr) {
        err = -EINVAL;
        goto unlock_out;
    }

    capi_controller[ctr->cnr - 1] = NULL;
    ncontrollers--;

    if (ctr->procent)
        remove_proc_entry(ctr->procfn, NULL);

    printk(KERN_NOTICE "kcapi: controller [%03d]: %s unregistered\n",
           ctr->cnr, ctr->name);

unlock_out:
    mutex_unlock(&capi_controller_lock);

    return err;
}
```

This patch ensures that `ctr->cnr` is within valid bounds (1 to `MAX_CAPI_CONTROLLERS`) before using it as an array index, preventing out-of-bounds access. The fix was included in Linux kernel versions 5.14.15 and later.

